function save(){if(demo)return;if(!browserSession.matches()){saveError=true;toast('다른 탭에서 접속 정보가 바뀌었습니다. 새로고침해 기존 인물을 확인해주세요.');return;}real=db;try{localStorage.setItem(KEY,JSON.stringify(real));localStorage.setItem(DIRTY_KEY,'1');saveError=false;}catch{saveError=true;toast('이 기기에 기록을 보관하지 못했습니다. 서버 저장 상태를 확인해주세요.');}if(!networkSync.active)cloudSync.schedule(real);}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
const encode=x=>{const bytes=new TextEncoder().encode(JSON.stringify(x));return btoa(String.fromCharCode(...bytes)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');};
function decode(x){if(x.length>512000)throw Error();return JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(x.replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0))));}
function readInvite(){const q=new URLSearchParams(location.hash.slice(1));if(q.has('join')){const code=q.get('join');if(!/^[a-zA-Z0-9_-]{20,80}$/.test(code)){setTimeout(()=>toast('초대 링크를 다시 확인해주세요.'),100);return;}invite={code,name:'새로운 인연',isKing:false};if(real.people[real.activeId])returnExistingInvite();else page='landing';return;}if(!q.has('invite'))return;try{const x=decode(q.get('invite'));if(!x||typeof x.id!=='string'||x.id.length>80||!/^[a-zA-Z0-9_-]+$/.test(x.id)||typeof x.name!=='string'||![...x.name].length||[...x.name].length>12||!['M','F'].includes(x.gender)||!Number.isInteger(x.type)||!TYPES[x.type]||typeof x.isKing!=='boolean')throw Error();if(x.ancestors!==undefined&&(!Array.isArray(x.ancestors)||x.ancestors.length>498))throw Error();for(const a of x.ancestors||[]){if(!a||typeof a.id!=='string'||!/^[a-zA-Z0-9_-]{1,80}$/.test(a.id)||['__proto__','constructor','prototype'].includes(a.id)||typeof a.name!=='string'||!a.name.trim()||[...a.name].length>12||!['M','F'].includes(a.gender)||!Number.isInteger(a.type)||!TYPES[a.type]||typeof a.isKing!=='boolean')throw Error();}if(x.chart!=null&&!validChart(x.chart)||(x.ancestors||[]).some(a=>a.chart!=null&&!validChart(a.chart)))throw Error();if(['__proto__','constructor','prototype'].includes(x.id))throw Error();const chain=[x,...x.ancestors||[]];if(new Set(chain.map(a=>a.id)).size!==chain.length||chain.slice(0,-1).some(a=>a.isKing)||!chain.at(-1).isKing)throw Error();invite=x;if(real.people[real.activeId])returnExistingInvite();else page='landing';}catch{setTimeout(()=>toast('초대장이 손상되었습니다. 링크를 다시 받아주세요.'),100);}}
function returnExistingInvite(){invite=null;returnedFromInvite=true;page='court';history.replaceState(null,'',location.pathname+location.search);}
readInvite();
function header(){return `<header class="site-header"><button class="brand" data-a="home" aria-label="내가왕 첫 화면"><span class="seal">王</span><span><b>내가왕<span class="red">.</span></b><small>MY LITTLE DYNASTY</small></span></button><nav class="nav" aria-label="주 메뉴">${[['court','내 조정'],['map','천하 지도'],['annals','신문·실록']].map(([p,t])=>`<button data-a="nav" data-page="${p}" class="${page===p?'active':''}" ${page===p?'aria-current="page"':''}>${t}</button>`).join('')}</nav><div class="header-right"><button class="tutorial-nav" data-a="tutorial">${icon('book',15)}<b>튜토리얼</b></button><button class="recovery-nav" data-a="recovery">복구 링크</button><button class="version" data-a="about">초안 · 체험판</button><button class="icon-btn" data-a="about" aria-label="이용 안내">${icon('info',17)}</button></div></header>`;}
function mobileNav(){return `<nav class="mobile-nav" aria-label="하단 메뉴">${[['court','crown','내 조정'],['map','map','천하 지도'],['recovery','book','복구 링크'],['invite','scroll','초대장']].map(([p,i,t])=>`<button data-a="${p==='invite'?'invite':p==='recovery'?'recovery':'nav'}" data-page="${p}" class="${page===p?'active':''}">${icon(i)}<span>${t}</span></button>`).join('')}</nav>`;}
function footer(){return `<footer class="footer"><span>내가왕 © 2026 · 작은 조정, 큰 자아.</span><span>재미로 보는 성향 놀이 <span style="margin:0 8px">·</span> <button data-a="recovery">복구 링크·백업</button> · <button data-a="tutorial">튜토리얼 다시 보기</button> · <button data-a="about">체험판 이용 안내</button></span></footer>`;}
function render(){mapController?.destroy();mapController=null;const views={landing:landing,court:court,map:mapView,entry:entryView,annals:()=>royalLife.archive(),};$('#app').innerHTML=`<div class="wrap">${header()}${demo?'':cloudBanner()}${saveError?'<div class="storage-warning">현재 기록을 저장하지 못하고 있습니다. 새로고침 전에 확인해주세요.</div>':''}<main id="main" tabindex="-1">${(views[page]||landing)()}</main>${footer()}</div>${mobileNav()}`;setTimeout(()=>{checkSummons();checkTutorial();},0);if(page==='map'&&mapLayout)mapController=mountMap($('#map-viewport'),$('#map-stage'),mapLayout,mapLayout.points[mapLayout.focusId]);}
const DIRTY_KEY='naegawang.unsynced.v3',REV_KEY='naegawang.server-revision.v3';
let serverBooting=true,cloudStatus='loading',cloudMessage='',cloudUpdated=null;
const cloudSync=createSync({fetcher:browserSession.fetch,onStatus(status,detail={}){cloudStatus=status;cloudMessage=detail.message||'';if(detail.updatedAt)cloudUpdated=detail.updatedAt;refreshCloudStatus();},onSaved(result,snapshot){try{localStorage.setItem(REV_KEY,String(result.revision));if(JSON.stringify(real)===JSON.stringify(snapshot))localStorage.removeItem(DIRTY_KEY);}catch{}},onConflict(){toast('다른 기기에서 바뀐 최신 기록이 있습니다. 최신 왕실을 먼저 불러와주세요.');}});
const networkSync=createNetworkSync({fetcher:browserSession.fetch,onWorld(data){
 const changed=JSON.stringify(real)!==JSON.stringify(data.world);real=data.world;
 try{localStorage.setItem(KEY,JSON.stringify(real));localStorage.removeItem(DIRTY_KEY);}catch{}
 if(!demo){db=real;if(changed&&!modal&&!quiz&&!registrationBusy){const oldView=mapController?.view,oldFocus=mapLayout?.points[mapLayout.focusId];render();if(oldView&&mapController){const nextFocus=mapLayout?.points[mapLayout.focusId],dx=(nextFocus?.x||0)-(oldFocus?.x||0),dy=(nextFocus?.y||0)-(oldFocus?.y||0);mapController.setView({...oldView,x:oldView.x-dx*oldView.scale,y:oldView.y-dy*oldView.scale});}}}
},onStatus(status,message){cloudStatus=status;cloudMessage=message||'';refreshCloudStatus();}});
async function refreshNetwork(){if(demo||document.visibilityState==='hidden'||serverBooting||registrationBusy||!networkSync.active)return;try{await networkSync.refresh();}catch{}}
const networkPoll=setInterval(refreshNetwork,10000);networkPoll.unref?.();
function networkAction(a,b){const cmd={type:a};
 switch(a){case 'bow':case 'reign-stay':case 'reign-independent':case 'nudge-ack':return cmd;
 case 'grant':return {...cmd,targetId:detailId,rank:selectedRank};
 case 'loyal-appoint':case 'loyal-dismiss':case 'royal-nudge':return {...cmd,targetId:detailId};
 case 'house-role':return {...cmd,targetId:b.dataset.id,office:((db.people[b.dataset.id]?.houseOffice||0)+1)%HOUSE_OFFICES.length};
 case 'shop-equip':return {...cmd,kind:b.dataset.kind,itemId:b.dataset.id};
 case 'life-council-open':return {...cmd,agendaId:b.dataset.id};
 case 'life-council-vote':return {...cmd,councilId:b.dataset.id,choice:Number(b.dataset.choice)};
 case 'life-council-close':return {...cmd,councilId:b.dataset.id};
 default:return null;}
}
async function runNetworkAction(a,b,cmd){
 if(!browserSession.matches())throw Error('다른 탭의 접속 정보가 바뀌었습니다. 새로고침해주세요.');
 const data=await networkSync.command(cmd);if(!demo){db=real;render();}
 if(a==='life-council-open')await royalLife.handle('life-council',{dataset:{id:data.resultId}});
 else if(a==='life-council-vote')await royalLife.handle('life-council',b);
 else if(a==='life-council-close'){if(data.resultId)await royalLife.handle('life-paper',{dataset:{id:data.resultId}});else closeModal();}
 else if(a==='house-role')householdModal(b.dataset.owner);
 else if(a==='shop-equip')shopModal();
 else if(['loyal-dismiss','royal-nudge'].includes(a))personModal(detailId);
 else if(a==='nudge-ack')closeModal();
 else if(a==='reign-independent'){closeModal();toast('새 나라를 세웠습니다. 초대한 인연은 천하지도에 그대로 이어집니다.');}
 else if(a!=='bow'){closeModal();toast('공유 천하에 반영했습니다.');}
}
const royalLife=createRoyalLifeUI({getDB:()=>db,me,esc,icon,openModal,save,render,toast,go});
function cloudText(){return {loading:'왕실 기록 연결 중',pending:'변경 사항 저장 대기',saving:'서버에 기록 중',saved:real.activeId?'공유 천하 연결됨':'서버 보관함 연결됨',error:'서버 저장 미완료',signin:'브라우저 접속 정보 확인 필요',conflict:'다른 기기의 새 기록 있음'}[cloudStatus]||'왕실 기록 확인';}
function refreshCloudStatus(){const el=$('#cloud-status-label');if(el)el.textContent=cloudText();const banner=$('#cloud-status');if(banner)banner.dataset.state=cloudStatus;}
function cloudBanner(){return `<div class="cloud-status" id="cloud-status" data-state="${cloudStatus}"><span class="cloud-dot"></span><span id="cloud-status-label">${cloudText()}</span>${cloudUpdated&&cloudStatus==='saved'?`<small>${new Date(cloudUpdated).toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'})}</small>`:''}${['error','signin','conflict'].includes(cloudStatus)?'<button data-a="cloud-latest">최신 왕실 확인</button>':''}<button data-a="recovery">고정 복구 링크</button></div>`;}
function markLocal(){try{localStorage.setItem(KEY,JSON.stringify(real));}catch{saveError=true;}}
function keepPrevious(){if(!real.activeId)return;try{localStorage.setItem(PREVIOUS_KEY,JSON.stringify(makeBackup(real)));}catch{}}
async function initializeServer({preferLatest=false}={}){
 if(serverBooting&&initializeServer.running)return;initializeServer.running=true;serverBooting=true;let local=real;let dirty=false,expected=0;try{dirty=localStorage.getItem(DIRTY_KEY)==='1';expected=Number(localStorage.getItem(REV_KEY)||0);}catch{}
 try{const recoveryToken=new URLSearchParams(location.hash.slice(1)).get('guest');if(recoveryToken&&!recoveryHandled){keepPrevious();await cloudSync.flush().catch(()=>{});cloudSync.pause();await browserSession.restore(recoveryToken);real=newWorld();if(!demo)db=real;local=real;dirty=false;expected=0;recoveryHandled=true;try{localStorage.removeItem(DIRTY_KEY);localStorage.removeItem(REV_KEY);}catch{}history.replaceState(null,'',location.pathname+location.search);}
  const connected=await networkSync.load();
  if(connected.world){real=connected.world;if(!demo){db=real;if(real.activeId&&invite)returnExistingInvite();if(page==='landing')page='court';}history.replaceState(null,'',location.pathname+location.search);cloudStatus='saved';return;}
  const data=await cloudSync.load();const resuming=new URLSearchParams(location.search).has('resume');
  if(data.world){const latest=validateWorld(data.world);if(dirty&&local.activeId&&!preferLatest&&!resuming){if(expected===data.revision){real=local;cloudSync.setRevision(expected);cloudSync.schedule(real);await (networkSync.active?networkSync.flush():cloudSync.flush());}else{real=local;cloudSync.pause();}}
   else{if(local.activeId&&dirty)keepPrevious();real=latest;const target=new URLSearchParams(location.search).get('resume');if(target&&real.people[target])real.activeId=target;try{localStorage.removeItem(DIRTY_KEY);}catch{}markLocal();}
  }else if(local.activeId){real=local;cloudSync.schedule(real);await (networkSync.active?networkSync.flush():cloudSync.flush());}else real=local;
  try{if(cloudSync.status!=='conflict')localStorage.setItem(REV_KEY,String(cloudSync.revision));}catch{}
  if(real.activeId&&cloudSync.status==='saved'){const connected=await networkSync.register({});real=connected.world;}
  if(!demo){db=real;if(real.activeId&&invite)returnExistingInvite();if(page==='landing'&&real.activeId&&!invite)page='court';}if(resuming)history.replaceState(null,'',location.pathname);
 }catch(e){cloudMessage=e.message;}finally{serverBooting=false;initializeServer.running=false;render();if(returnedFromInvite){returnedFromInvite=false;toast('다시 오셨군요. 새 인물을 만들지 않고 기존 인물로 돌아왔습니다.');}}
}
function latestReturnLink(){const url=new URL(appBase());url.searchParams.set('resume',real.activeId||'latest');if(browserSession.token)url.hash=new URLSearchParams({guest:browserSession.token}).toString();return url.href;}
async function showLatestChoice(){openModal(`<div class="eyebrow">LATEST ROYAL RECORD</div><h2>최신 왕실을 확인합니다.</h2><p class="lead">서버에 마지막으로 저장된 기록을 불러옵니다. 현재 기기의 기록은 별도 백업으로 보관합니다.</p><button class="button full" data-a="cloud-load-confirm">서버의 최신 기록 불러오기</button>${cloudMessage?`<p class="tiny muted" style="margin-top:12px">${esc(cloudMessage)}</p>`:''}`);}

function landing(){return `<div class="landing">${invite?`<div class="invite-banner">${icon('scroll',29)}<div><b>${esc(invite.name)}${invite.isKing?(invite.gender==='F'?'여왕':'왕'):''}의 초대장이 도착했습니다.</b><p>사주 정보로 캐릭터와 왕실 궁합을 정하고 입장합니다.</p></div></div>`:''}<div class="landing-hero"><div class="landing-copy"><div class="eyebrow">사주로 시작하는 나의 작은 왕조</div><h1>내가 왕이 될<br><em>상인가?</em></h1><p>이름과 생년월일시로 알아보는 나의 왕실 캐릭터.<br>사주 기반 성향분석으로 게임을 시작합니다.</p><div class="landing-actions"><button class="button" data-a="start">${invite?'초대받은 나라에 입장하기':'나의 왕조 시작하기'} ${icon('arrow')}</button><button class="button light" data-a="demo">조정 먼저 구경하기</button></div><p class="note">회원가입 없이 시작 · 같은 브라우저에서 자동 재접속</p><button class="text-btn" style="margin-top:12px" data-a="recovery">이미 나라가 있나요? 최신 복구 링크로 돌아오기 ↗</button></div><div class="royal-scene"><span class="scene-label">과인의 나라에 온 것을 환영하노라</span><span class="scene-stamp">천하<br>태평</span><img src="assets/lazy-king.webp" alt="느긋하게 기대앉은 코믹한 조선 왕" fetchpriority="high"><div class="scene-caption">“급한 일이더냐? 누워서도 들을 수 있느니라.”</div></div></div><div class="entrance-steps"><div class="entrance-step"><span class="step-no">一</span><div><b>사주로 정하는 나의 캐릭터</b><p>생년월일시와 성별을 입력하면<br>왕실에서의 성향이 정해집니다.</p></div></div><div class="entrance-step"><span class="step-no">二</span><div><b>함께한 인연은 나의 힘</b><p>초대한 사람이 왕으로 독립해도<br>내 인맥 등급과 인연은 그대로.</p></div></div><div class="entrance-step"><span class="step-no">三</span><div><b>경배가 빛나는 왕실</b><p>독립한 나라의 경배도 절반씩.<br>모은 금화로 왕실을 치장하세요.</p></div></div></div><p class="landing-notice">아뜰리에 사주 만세력과 해석을 바탕으로 한 재미용 게임입니다. 사주 정보는 캐릭터·궁합 산출에 사용하며 상세 풀이는 자동으로 펼치지 않습니다.</p></div>`;}

function demoBar(){if(!demo)return '';return `<div class="demo-bar"><div class="demo-left"><span class="pill red">샘플 조정</span><span>인물을 바꿔 경배·즉위를 체험하세요.</span></div><div style="display:flex;gap:10px;align-items:center"><label><span class="tiny muted">체험 인물 </span><select id="demo-person" aria-label="체험할 인물 선택">${Object.values(db.people).map(p=>`<option value="${esc(p.id)}" ${p.id===db.activeId?'selected':''}>${title(p)} · ${role(p)}</option>`).join('')}</select></label><button class="text-btn" data-a="exit-demo">체험 종료</button></div></div>`;}
function avatar(p,{size='',pos='',forceKing=false}={}){const rs=royalStyle(db,p),c=border(networkLevelCount(db,rs.king?.id)).color;return `<span class="avatar" data-frame="${rs.frame.id}" style="--ring:${c};${size}"><img src="${image(p,forceKing)}" alt="${esc(p.name)} ${role(p)} 캐릭터" loading="lazy">${avatarFrame(rs.frame.id)}${pos?`<span class="pos">${pos}</span>`:''}</span>`;}
function profileCard(p){const sub=subjects(db,p.id),ind=independent(db,p.id),rs=royalStyle(db,p),b=border(networkLevelCount(db,rs.king?.id)),t=TYPES[characterType(p)],dep=isDependent(db,p);return `<div class="sovereign-card" data-decor="${rs.decor.id}" style="--ring:${b.color}"><div class="royal-card-top"><span>御眞 · ${p.isKing?'군주의 초상':dep?'식솔의 하루':'입궐의 기록'}</span><span>${p.isKing?'天 下 泰 平':'忠 誠 忠 誠'}</span></div><div class="portrait-circle ${p.isKing?'':isDependent(db,p)?'subject dependent':'subject'}" data-frame="${rs.frame.id}"><img src="${image(p)}" alt="${esc(p.name)}의 캐릭터" fetchpriority="high"></div>${compatBadge(p)}<h2>${title(p)}</h2><span class="destiny-source">${dep?'현재 집안 직책':validChart(p.chart)?'사주로 정해진 '+(p.isKing?'군주':'관직'):'사주 등록 전 캐릭터'}</span><p class="type-name">${p.isKing?royalCharacterName(p):dep?HOUSE_OFFICES[p.houseOffice||0]:officeFor(p)[0]}</p><div class="royal-quote">“${p.isKing?t.quote:dep?'밥은 여기서 먹고, 꿈은 왕으로 꾸겠소.':officeFor(p)[1]}”</div>${p.isKing?`<span class="pill gold">${prestige(p)}</span><div class="stat-row"><div><b>${networkLevelCount(db,p.id)}</b><small>인맥 · 독립 왕 포함</small></div><div><b>${n(p.totalBows)}</b><small>누적 받은 경배</small></div><div><b>${n(p.gold)}</b><small>금화 · 국고</small></div></div>`:`<div class="stat-row"><div><b>${household(db,p.id).length}</b><small>내가 먹여 살리는 식솔</small></div><div><b>${n(p.bows)}</b><small>올린 경배</small></div><div><b>${n(p.gold)}</b><small>모은 금화</small></div></div><p class="tiny muted">독립한 인연에게서 받은 경배 ${n(p.inheritedBows||0)}회 · 금화는 독립 후에도 이어집니다.</p>`}<button class="destiny-open" data-a="person" data-id="${esc(p.id)}">사주가 정한 내 캐릭터 알아보기 ↗</button><button class="button saju-profile-button full" data-a="saju-result">${icon('book',19)} 내 사주 결과 보기</button><button class="button full" data-a="invite">${icon('scroll')} ${p.isKing?'과인의 조정에 초대하기':'내 집안에 지인 초대하기'}</button><div class="border-description"><span class="color-dot"></span>${rs.frame.name}${p.isKing?' · '+b.name+' · 인맥 '+networkLevelCount(db,p.id)+'명':` · ${rs.king?esc(rs.king.name)+' 왕실':'집안'} 테두리`}</div><button class="royal-backup-link" data-a="recovery">${icon('book',13)} 왕실 기록 보관 · 복구 링크</button></div><div class="king-side-note"><b>${p.isKing?'금화는 써도, 명성은 남는다.':'식솔이어도 왕이 될 수 있습니다.'}</b><br>${p.isKing?'독립 왕도 인맥 수에 포함됩니다. 직접 초대한 왕이 받는 경배의 50%도 과인에게 쌓입니다.':'초대한 지인이 한 명 이상 있으면 잔류와 독립을 직접 선택합니다. 독립하면 같은 성향의 군주가 됩니다.'}</div>`;}
function loyalPanel(king){const list=loyalSubjects(db,king.id);return `<section class="loyal-panel"><div class="section-label"><h2>전하의 두 충신 <span class="number">${list.length}/2</span></h2><span class="tiny muted">경배 순위와 별도 · 왕이 직접 지명</span></div><div class="loyal-grid">${[0,1].map(i=>list[i]?`<button class="loyal-seat occupied" data-a="person" data-id="${esc(list[i].id)}">${avatar(list[i])}<div><small>최측근 ${i+1}</small><b class="full-name">${compactName(list[i])}</b><span>사주 자동 관직</span></div></button>`:`<div class="loyal-seat"><span class="loyal-empty">${icon('crown',24)}</span><div><small>최측근 ${i+1}</small><b>아직 빈자리</b><span>신하를 눌러 충신으로 지명</span></div></div>`).join('')}</div></section>`;}
function subjectCard(p,i){return `<article class="subject-card"><button class="subject-open" data-a="person" data-id="${esc(p.id)}">${royalGranted(p)?'<span class="favor-tag">♛ 낙하산 총애</span>':''}<div class="subject-top">${avatar(p,{pos:String(i+1)})}<span class="subject-info"><b class="subject-name full-name">${compactName(p)}</b><small class="destiny-caption">사주 자동 관직</small>${household(db,p.id).length?`<span class="house-badge">먹여 살리는 식솔 ${household(db,p.id).length}명</span>`:''}${loyalSubjects(db,p.liegeId).some(x=>x.id===p.id)?'<span class="loyal-badge">최측근 충신</span>':''}</span></div>${compatBadge(p)}<div class="subject-bottom"><span class="rank-text"><i class="rank-dot"></i>${rank(p)+1}등급 · ${RANKS[rank(p)]}</span><span class="bow-count">${icon('bow',13)} ${n(p.bows)}</span></div></button><button class="compatibility-button" data-a="compatibility" data-id="${esc(p.id)}">${icon('people',16)} 왕과의 궁합 사주 보기 ${icon('arrow',14)}</button></article>`;}

function court(){const p=me();if(!p)return landing();return `${demoBar()}<div class="page-head"><div><div class="eyebrow">THE ROYAL COURT</div><h1>${p.isKing?'과인의 조정':isDependent(db,p)?'식솔의 하루':'신하의 하루'}</h1><p>${p.isKing?'왕 노릇은 처음이라도, 총애는 확실하게.':'몸은 신하이나, 마음속에는 이미 왕관 하나.'}</p></div></div><div class="saju-action-row"><button class="saju-feature" data-a="saju-result"><span class="saju-feature-seal">命</span><span><b>내 사주 결과 보기</b><small>사주 원국 · 타고난 성향 · 운세 풀이</small></span><span class="saju-feature-arrow">${icon('arrow',25)}</span></button>${!p.isKing?`<button class="button gold saju-pair-main" data-a="compatibility" data-id="${esc(sovereign(db,p.id)?.id||p.liegeId)}">${icon('people',22)} 왕과의 궁합 사주</button>`:''}</div>${!p.birth?'<div class="return-guide">이전 캐릭터의 인연·경배·금화는 그대로입니다. 사주 정보를 등록하면 새 기준으로 캐릭터와 궁합을 정합니다. <button data-a="edit-saju">사주 정보 등록 ↗</button></div>':''}<div class="return-guide">복구 링크는 언제든 상단·하단의 ‘복구 링크’에서 확인할 수 있습니다. 같은 브라우저에서는 기존 인물로 자동 접속합니다. <button data-a="recovery">지금 링크 확인 ↗</button></div><div class="court-grid"><aside>${profileCard(p)}</aside><section>${p.isKing?royalCourt(p):subjectCourt(p)}</section></div>`;}
function royalCourt(p){const sub=subjects(db,p.id),ind=independent(db,p.id);return `<div class="decree-banner"><span class="decree-seal">敎</span><div><b>관직은 사주가, 총애는 과인이 정한다.</b><p>관직·초상은 사주로 자동 배정됩니다. 신하를 눌러 충신 지명·특별 총애·곤장 독촉을 내리세요.</p></div><button data-a="ranks">등급 보기</button></div>${royalTreasury(p)}${royalLife.panel()}${loyalPanel(p)}<div class="section-label"><h2>과인의 신하들 <span class="number">${sub.length}</span></h2><span class="tiny muted">누적 경배 순</span></div>${sub.length?`<div class="roster">${sub.map(subjectCard).join('')}</div>`:`<div class="empty"><h3>옥좌는 있는데, 들어줄 사람이 없구나.</h3><p>첫 신하를 맞이하고 조정을 시작해보세요.</p><button class="button light" data-a="invite">초대장 쓰기 ${icon('arrow',15)}</button></div>`}${demo?`<div style="margin-top:13px;text-align:right"><button class="arrow-link" data-a="sample-add">${icon('plus',14)} 체험용 신하 입궐시키기</button></div>`:''}<div class="independent-section"><div class="section-label"><h2>독립한 군주들 <span class="number">${ind.length}</span></h2><button class="arrow-link" data-a="nav" data-page="map">천하 지도 ${icon('arrow',14)}</button></div>${ind.length?`<div class="independent-list">${ind.map(x=>`<button class="independent-card" data-a="person" data-id="${esc(x.id)}"><span class="house-portrait">${avatar(x)}${compatBadge(x)}</span><div><b>${title(x)}</b><p>과인의 나라 출신 · 신하 ${subjects(db,x.id).length}명 · 인연 유지</p></div><span class="arrow">${icon('arrow',17)}</span></button>`).join('')}</div>`:'<p class="small muted">아직 독립한 군주가 없습니다. 신하의 첫 초대가 새로운 나라의 시작입니다.</p>'}</div>${chronicle()}`;}
function chronicle(){return royalLife.chronicle();}
function subjectCourt(p){const caregiver=db.people[p.liegeId],dep=isDependent(db,p),r=rank(p),next=THRESHOLDS[r+1];return `${royalLife.panel()}${reignChoice(p)}<div class="subject-panel"><div class="subject-view"><div class="eyebrow">${dep?'MY HOUSEHOLD':'LONG LIVE THE '+(caregiver.gender==='F'?'QUEEN':'KING')}</div><div class="bow-stage">${avatar(caregiver,{size:'width:140px;height:140px;margin:0 auto 18px;'})}${compatBadge(caregiver)}<h3>${title(caregiver)}</h3>${dep?`<p>나를 먹여 살리는 우리 집안의 가장.</p><button class="button light" data-a="household" data-id="${esc(caregiver.id)}">우리 집안 보기</button><div class="note-box">왕은 내 직책을 바꿀 수 없습니다.<br>집안 일은 나를 초대한 ${esc(caregiver.name)}이 정합니다.</div>`:`<p>전하 아래, 오늘도 굽신굽신.</p><button class="button bow-button" data-a="bow">${icon('bow',23)} 경배 올리기</button><p>내가 올린 경배</p><b class="bow-number" id="bow-number">${n(p.bows)}</b><div id="rank-progress"><span class="pill gold">${r+1}등급 · ${RANKS[r]}</span><div class="progress"><i style="width:${next?Math.min(100,p.bows/next*100):100}%"></i></div><span class="tiny muted">${next?`다음 등급까지 ${n(next-p.bows)}회`:'전하의 총애가 지극하옵니다.'}</span></div><p class="tiny muted">왕실 경배 <b id="king-bow-total">${n(caregiver.totalBows)}</b>회 · 국고 금화 <b id="king-gold">${n(caregiver.gold)}</b>개<br>10회당 금화 1개 · 1인 하루 100회까지 금화 기여</p>`}</div></div><div class="subject-view"><div class="eyebrow">A CROWN OF MY OWN</div><h2 style="margin-top:10px">밥줄은 여기,<br>야망은 저기.</h2><p>신하든 식솔이든 초대는 자유.<br>지인이 들어오면 남을지 독립할지 고릅니다.</p><div class="how-list"><div>나의 초대장을 보낸다.</div><div>지인은 나의 식솔로 들어온다.</div><div>함께 남거나, 내 나라를 세운다.</div></div><button class="button jade full" data-a="invite">나도 지인 초대하기 ${icon('arrow')}</button>${demo?'<button class="text-btn" data-a="sample-add" style="margin-top:15px">체험용 지인 한 명 입장시키기 ↗</button>':''}</div></div>${householdPanel(p)}${chronicle()}`;}
function reignChoice(p){if(p.isKing||!household(db,p.id).length)return '';return `<section class="choice-banner"><span class="seal">立</span><div><b>${p.recruitChoice==='pending'?'새 식솔이 들어왔습니다. 왕관을 쓰시겠소?':'밥줄을 지킬 것인가, 왕관을 쓸 것인가.'}</b><p>남으면 내 식솔을 직접 돌봅니다. 독립하면 직속 식솔은 신하가 되고, 그 아래 집안도 함께 이동합니다.</p><div class="actions">${p.recruitChoice==='pending'?'<button class="button light" data-a="reign-stay">여기에 남겠소</button>':''}<button class="button gold" data-a="reign-independent">${kingLabel(p)}으로 독립하겠소</button></div></div></section>`;}
function householdPanel(p){const list=household(db,p.id);return `<section class="household-panel"><div class="section-label"><h2>내가 먹여 살리는 식솔 <span class="number">${list.length}</span></h2><button class="arrow-link" data-a="household" data-id="${esc(p.id)}">집안 관리 ↗</button></div>${list.length?`<div class="household-roster">${list.map(x=>`<button class="household-member" data-a="person" data-id="${esc(x.id)}"><span class="house-portrait">${avatar(x)}${compatBadge(x)}</span><span><b>${esc(x.name)}</b><small>${HOUSE_OFFICES[x.houseOffice||0]} · 자기 식솔 ${household(db,x.id).length}명</small></span></button>`).join('')}</div>`:'<p class="small muted">지인이 내 초대로 들어오면 이 집안의 첫 식솔이 됩니다.</p>'}</section>`;}
function householdModal(id){const owner=db.people[id];if(!owner||owner.isKing)return;const list=household(db,id),own=me()?.id===id;openModal(`<div class="eyebrow">A LITTLE HOUSEHOLD</div><h2>${esc(owner.name)}이 먹여 살리는 집안</h2><p class="lead">${own?'내 직속 식솔의 집안 직책을 정합니다.':'집안 관리는 '+esc(owner.name)+'만 할 수 있습니다.'} 식솔도 자기 지인을 초대하고 독립할 수 있습니다.</p><div class="household-roster">${list.map(x=>`<article class="household-member"><span class="house-portrait">${avatar(x)}${compatBadge(x)}</span><div><b>${esc(x.name)}</b><small>${HOUSE_OFFICES[x.houseOffice||0]}</small><div class="actions"><button class="text-btn" data-a="person" data-id="${esc(x.id)}">인물 보기</button>${own?`<button class="text-btn" data-a="house-role" data-owner="${esc(id)}" data-id="${esc(x.id)}">집안 직책 바꾸기</button>`:''}${household(db,x.id).length?`<button class="text-btn" data-a="household" data-id="${esc(x.id)}">그 아래 식솔 ${household(db,x.id).length}명 ↗</button>`:''}</div></div></article>`).join('')||'<p class="muted">아직 식솔이 없습니다.</p>'}</div><div class="note-box">왕의 충신 임명·직권 승급·곤장은 직속 신하에게만 적용됩니다. 이 집안의 식솔에게는 적용되지 않습니다.</div>${demo?`<button class="button full" data-a="switch" data-id="${esc(id)}">${esc(owner.name)}으로 집안 관리 체험</button>`:''}`,{wide:true});}
function royalTreasury(p){const rs=royalStyle(db,p);return `<section class="royal-treasury" data-decor="${rs.decor.id}"><div class="palace-ornament" aria-hidden="true"><span>日</span><b>王</b><span>月</span></div><div class="treasury-copy"><div class="eyebrow">THE ENVY OF THE KINGDOMS</div><h2>${rs.decor.name}</h2><p>“저 왕은 경배를 얼마나 받는 게냐…”</p><div class="prestige-stats"><span><b>${n(p.totalBows)}</b> 누적 경배</span><span><b>${n(p.inheritedBows||0)}</b> 연결 경배</span><span><b>${n(p.gold)}</b> 금화</span><span class="pill gold">${prestige(p)}</span></div></div>${p.id===db.activeId?'<button class="button gold" data-a="royal-shop">왕실 꾸미기 ↗</button>':'<span class="pill gold">다른 나라의 왕실 구경</span>'}<small class="treasury-note">10회 경배 = 금화 1개 · 직접 초대한 독립 왕의 경배는 50% 추가 적립 · 하루 1인 100회까지 금화 기여</small></section>`;}
function shopModal(){const p=me();if(!p?.isKing)return;openModal(`<div class="eyebrow">THE ROYAL ATELIER</div><h2>돈 쓴 티 좀 내보겠소.</h2><p class="lead">국고 <b class="gold-text">금화 ${n(p.gold)}개</b> · 누적 받은 경배 ${n(p.totalBows)}회<br>금화를 모아 왕실을 업그레이드하세요. 구매한 장식은 계속 보관되며 다시 적용할 때는 무료입니다.</p>${[['frame','왕실 공통 테두리',FRAMES,'ownedFrames'],['decor','궁궐 꾸미기',DECOR,'ownedDecor']].map(([kind,label,items,owned])=>`<h3 class="shop-heading">${label}</h3><div class="shop-grid">${items.map(x=>{const have=p[owned].includes(x.id),equipped=p[kind]===x.id;return `<article class="shop-item ${equipped?'equipped':''}">${kind==='frame'?`<div class="shop-frame-preview">${`<span class="avatar" data-frame="${x.id}"><img src="${image(p)}" alt="${x.name} 미리보기"></span>`}</div>`:`<div class="decor-swatch" data-decor="${x.id}" aria-hidden="true"><span>日</span><b>王</b><span>月</span></div>`}<b>${x.name}</b><p>${x.desc}</p>${!have?`<small class="shop-needed">${p.gold<x.cost?`금화 ${n(x.cost-p.gold)}개 더 필요`:"구매할 수 있습니다"}</small>`:''}<button class="button ${have?'light':'gold'} full" data-a="shop-equip" data-kind="${kind}" data-id="${x.id}" ${equipped||!have&&p.gold<x.cost?'disabled':''}>${equipped?'적용 중':have?'다시 적용':`금화 ${x.cost}개 · 구매·적용`}</button></article>`;}).join('')}</div>`).join('')}<div class="note-box">테두리는 왕·여왕과 그 나라의 신하·식솔에게 함께 적용됩니다. 독립하면 새 나라의 꾸밈을 사용합니다. 신하 수에 따른 기본 테두리 색은 유지됩니다.</div>`,{wide:true});}
function kingdomRanking(){const kings=Object.values(db.people).filter(p=>p.isKing).sort((a,b)=>(b.totalBows||0)-(a.totalBows||0)||a.joined-b.joined);return `<section class="kingdom-ranking"><div class="section-label"><h2>우리 천하의 경배 자랑</h2><span class="tiny muted">현재 세계에 연결된 나라 · 전체 서비스 순위 아님</span></div><div class="ranking-list">${kings.map((p,i)=>`<button class="ranking-row" data-a="person" data-id="${esc(p.id)}"><strong>${i+1}</strong>${avatar(p)}<span><b>${title(p)}</b><small>${prestige(p)} · ${royalStyle(db,p).decor.name}</small></span><span class="ranking-bows"><b>${n(p.totalBows)}</b><small>누적 경배</small></span></button>`).join('')}</div><p class="tiny muted">경배 기록은 독립과 장식 구매로 줄어들지 않습니다.${demo?' 샘플 금화·경배는 체험용 설정입니다.':''}</p></section>`;}
function nudgeActions(p){return `<div class="nudge-action"><span class="paddle" aria-hidden="true">杖</span><div><b>경배가 뜸하구나?</b><p>곤장을 누르면 해당 인물 화면에 경배 독촉창이 뜹니다.</p><small>지금까지 ${n(p.summons?.count||0)}대 · ${p.summons&&!p.summons.read?'전교 확인 대기':'확인된 전교 없음'}</small></div><button class="button" data-a="royal-nudge">곤장 한 대!</button></div>`;}
function checkTutorial(){const p=me();if(demo||serverBooting||modal||quiz||entryPending||page!=='court'||!p||p.external)return;if(!p.tutorialSeen?.[tutorialRole(p)])startTutorial();}
function tutorialChooser(){openModal(`<div class="eyebrow">FIRST DAY AT THE PALACE</div><h2>왕실 생활, 미리 익혀보세요.</h2><p class="lead">각각 다섯 장이면 충분합니다. 실제 기록을 바꾸지 않고 경배와 총애도 연습해볼 수 있습니다.</p><div class="tutorial-roles"><button class="button jade" data-a="tutorial-role" data-role="subject">${icon('people')} 신하 튜토리얼</button><button class="button" data-a="tutorial-role" data-role="king">${icon('crown')} 왕 튜토리얼</button></div>`);}
function startTutorial(requested){if(entryPending||quiz)return;const p=me(),r=['king','subject'].includes(requested)?requested:tutorialRole(p),actual=!!p&&r===tutorialRole(p),preview={...(p||{name:'새내기',gender:'M',type:0}),isKing:r==='king'};tutorialState={role:r,personId:actual?p.id:null,preview,dependent:actual&&isDependent(db,p),step:0,bow:0,favor:0,steps:tutorialSteps(r,{dependent:actual&&isDependent(db,p),queen:p?.gender==='F'})};drawTutorial();}
function completeTutorial(){const t=tutorialState;tutorialState=null;if(!t)return;const p=me();if(p&&p.id===t.personId&&tutorialRole(p)===t.role){p.tutorialSeen={subject:!!p.tutorialSeen?.subject,king:!!p.tutorialSeen?.king,[t.role]:true};if(!demo&&networkSync.active)networkSync.command({type:'tutorial',role:t.role}).catch(e=>toast(e.message));else save();}}
function tutorialPreview(t,step){switch(step.preview){
 case 'portrait':return `<div class="tutorial-portrait"><img src="${characterImage(t.preview,{dependent:t.dependent,forceKing:t.role==='king'})}" alt="${esc(t.preview.name)}의 ${t.role==='king'?'군주':t.dependent?'식솔':'신하'} 캐릭터"><div><small>${t.dependent?'지금은 식솔 · 독립하면 군주':'사주로 정해진 나의 캐릭터'}</small><b>${esc(t.role==='king'?royalCharacterName(t.preview):t.dependent?HOUSE_OFFICES[0]:officeFor(t.preview)[0])}</b><span>${esc(t.preview.name)}의 왕실 생활, 지금 시작합니다.</span></div></div>`;
 case 'loyal':return `<div class="tutorial-loyal"><span>${icon('crown',27)}<b>전하</b></span><div>${[1,2].map(i=>`<span>${icon('people',22)}<b>최측근 ${i}</b></span>`).join('')}</div></div><p class="tutorial-location">내 조정 → 신하 사진 → 충신으로 삼기</p>`;
 case 'bow':return `<div class="tutorial-practice"><small>경배 연습</small><strong aria-live="polite">${t.bow}<em>회</em></strong><button class="button jade" data-a="tutorial-practice">${icon('bow')} 경배 연습하기</button><p>연습 · 실제 경배와 금화에 반영되지 않습니다.</p></div>`;
 case 'favor':return `<div class="tutorial-practice"><small>특별 총애 연습</small><strong class="tutorial-rank" aria-live="polite">${t.favor+1}등급 · ${RANKS[t.favor]}</strong><button class="button" data-a="tutorial-practice" ${t.favor===RANKS.length-1?'disabled':''}>${icon('scroll')} 한 등급 올려보기</button><p>연습 · 실제 신하의 등급·관직·경배는 변하지 않습니다.</p></div>`;
 case 'treasury':return `<div class="tutorial-treasury"><span class="avatar" data-frame="dragon"><img src="${characterImage(t.preview,{forceKing:true})}" alt="화려한 왕실 테두리 미리보기"></span><div><b>경배가 쌓이면, 왕실이 빛납니다.</b><span>공통 테두리 · 궁궐 꾸미기</span></div></div><p class="tutorial-location">내 조정 → 왕실 꾸미기</p>`;
 case 'household':return `<div class="tutorial-route"><span>${icon('people',23)} 나</span>${icon('arrow')}<span>${icon('scroll',23)} 초대장</span>${icon('arrow')}<span>${icon('people',23)} 내 식솔</span></div><p class="tutorial-location">내 조정 → ${t.dependent&&t.step===1?'우리 집안 보기':'내 집안에 지인 초대하기'}</p>`;
 case 'choice':return `<div class="tutorial-choice"><span>여기에 남겠소<small>내 식솔을 직접 돌보기</small></span><span>${kingLabel(t.preview)}으로 독립하겠소<small>내 나라의 신하로 맞이하기</small></span></div><p class="tutorial-location">지인을 초대한 뒤 → 내 조정의 잔류·독립 선택</p>`;
 default:return `<div class="tutorial-map-guide">${icon('map',38)}<div><b>천하 지도</b><span>한 손가락 이동 · 두 손가락 확대·축소</span><small>−　전체 보기　＋　내 나라</small></div></div><p class="tutorial-location">재접속 준비 → 상단 ‘복구 링크’ 보관</p>`;
}}
function drawTutorial(){const t=tutorialState;if(!t)return;const step=t.steps[t.step],last=t.step===t.steps.length-1;openModal(`<div class="tutorial" data-tutorial-role="${t.role}" data-tutorial-step="${t.step}"><div class="tutorial-kicker"><span class="eyebrow">${t.role==='king'?'御前 · 군주의 첫날':t.dependent?'入門 · 식솔의 첫날':'入闕 · 신하의 첫날'}</span><span>${t.step+1} / ${t.steps.length}</span></div><div class="tutorial-progress" role="progressbar" aria-label="튜토리얼 진행" aria-valuemin="1" aria-valuemax="${t.steps.length}" aria-valuenow="${t.step+1}">${t.steps.map((_,i)=>`<i class="${i<=t.step?'done':''}"></i>`).join('')}</div><div class="tutorial-heading">${icon(step.icon,23)}<h2>${esc(step.title)}</h2></div><p class="tutorial-copy">${esc(step.text)}</p><div class="tutorial-preview">${tutorialPreview(t,step)}</div><div class="tutorial-hint">${icon('info',16)}<p>${esc(step.hint)}</p></div><div class="tutorial-actions"><button class="text-btn" data-a="tutorial-skip">건너뛰기</button><div>${t.step?'<button class="button light" data-a="tutorial-prev">이전</button>':''}<button class="button" data-a="${last?'tutorial-finish':'tutorial-next'}">${last?'알겠노라 · 시작하기':'다음 '+icon('arrow',16)}</button></div></div><p class="tutorial-replay-note">언제든 상단 ‘튜토리얼’에서 다시 볼 수 있습니다.</p></div>`,{replace:!!modal?.tutorial,tutorial:true});}

function checkSummons(){const p=me();if(serverBooting&&!demo)return;if(modal||quiz||!p||p.isKing||!p.summons||p.summons.read)return;const king=db.people[p.summons.fromId];if(!king)return;openModal(`<div class="nudge-notice"><span class="paddle" aria-hidden="true">杖</span><div class="eyebrow">A MOST URGENT ROYAL MESSAGE</div><h2>경배를 빨리 하라!</h2><p class="lead">${title(king)}이 곤장을 ${n(p.summons.count)}대 내렸습니다.<br>“과인의 무릎이 아니라, 그대의 정성이 부족하구나!”</p><p class="tiny muted">우스꽝스러운 왕실 독촉입니다. 경배·등급·금화는 변하지 않습니다.</p><button class="button full" data-a="nudge-ack">알겠사옵니다 · 경배하러 가기</button></div>`);}

function mapView(){if(!me())return `<div class="page-head"><div><h1>천하 지도</h1><p>나라와 나라, 사람과 사람의 연결.</p></div></div><div class="empty"><h3>아직 그대의 나라가 없습니다.</h3><p>복구 링크로 돌아오거나 샘플 천하를 구경해보세요.</p><button class="button" data-a="recovery">복구 링크</button> <button class="button light" data-a="demo" data-page="map">샘플 지도 보기</button></div>`;
 const layout=radialLayout(db,db.activeId,{households:showHouseholds}),all=Object.values(db.people).filter(p=>!layout.points[p.id]?.hidden);mapLayout=layout;const {points,clusters,width,height}=layout;
 return `${demoBar()}<div class="page-head"><div><div class="eyebrow">THE CONNECTED KINGDOMS</div><h1>천하 지도</h1><p>초대한 사람이 다시 초대하면, 하나의 천하에서 인연이 계속 이어집니다.</p></div><button class="button light" data-a="invite">${icon('plus',15)} 인연 잇기</button></div><div class="map-legend"><span><i class="legend-line"></i>군주 주위의 현직 신하</span><span><i class="legend-line dashed"></i>초대한 왕 → 독립 왕 · 선후관계</span><span><i class="legend-line" style="border-color:#a88740"></i>직속 충신 두 자리</span></div><div class="map-board"><div class="map-tools" role="group" aria-label="지도 보기 조절"><button data-a="map-out" aria-label="지도 축소">−</button><output data-map-scale aria-live="polite">100%</output><button data-a="map-in" aria-label="지도 확대">＋</button><span class="map-tool-separator"></span><button class="map-tool-text" data-a="map-fit">전체 보기</button><button class="map-tool-text" data-a="map-center">내 나라</button><button class="map-tool-text" data-a="map-households">${showHouseholds?'식솔 접기':'식솔 펼치기'}</button></div><div class="map-viewport" id="map-viewport" tabindex="0" role="region" aria-label="방사형 천하 지도. 방향키로 이동하고 더하기 빼기 키로 확대 축소합니다."><div class="map-terrain" data-map-terrain aria-hidden="true"></div><div class="map-stage" id="map-stage" style="width:${width}px;height:${height}px"><svg class="map-line-layer" viewBox="0 0 ${width} ${height}" aria-hidden="true"><defs><marker id="royal-arrow" viewBox="0 0 12 12" refX="11" refY="6" markerWidth="11" markerHeight="11" orient="auto-start-reverse"><path d="M1 1 L11 6 L1 11 Z" fill="#a96b56"/></marker></defs>${clusters.map(c=>`<circle cx="${c.x}" cy="${c.y}" r="${c.radius}" fill="${border(networkLevelCount(db,c.id)).color}" fill-opacity=".035" stroke="${border(networkLevelCount(db,c.id)).color}" stroke-opacity=".32" stroke-dasharray="3 7"/><text x="${c.x}" y="${c.y-c.radius+25}" text-anchor="middle" class="country-label">${esc(c.king.name)}${kingLabel(c.king)} · 경배 ${n(c.king.totalBows)}회 · ${prestige(c.king)}</text>`).join('')}${all.filter(p=>p.inviterId&&points[p.inviterId]).map(p=>{const a=points[p.isKing?p.inviterId:p.liegeId],b=points[p.id];if(!a)return '';if(b.isLoyal){const joint=a.y+MAP_NODE_METRICS.king.bottom+28;return `<path d="M${a.x},${a.y+MAP_NODE_METRICS.king.bottom+10} V${joint} H${b.x} V${b.y-MAP_NODE_METRICS.subject.top}" fill="none" stroke="#a88740" stroke-width="2.2"/>`;}const len=Math.hypot(b.x-a.x,b.y-a.y)||1,ux=(b.x-a.x)/len,uy=(b.y-a.y)/len,offset=p.isKing?68:0;return `<path d="M${a.x+ux*offset},${a.y+uy*offset} L${b.x-ux*offset},${b.y-uy*offset}" ${p.isKing?'marker-end="url(#royal-arrow)"':''} fill="none" stroke="${p.isKing?'#a96b56':'#8b9a80'}" stroke-width="${p.isKing?2:1.4}" ${p.isKing?'stroke-dasharray="7 7"':''}/>`;}).join('')}</svg>${all.map(p=>{const pos=points[p.id],size=(p.isKing?MAP_NODE_METRICS.king:MAP_NODE_METRICS.subject).portrait;return `<button data-decor="${royalStyle(db,p).decor.id}" class="map-node ${p.isKing?'king':''} ${p.id===db.activeId?'is-me':''} ${pos.isLoyal?'loyal-node':''}" style="left:${pos.x}px;top:${pos.y}px;--map-card-width:${MAP_NODE_METRICS.width}px;--map-portrait-size:${size}px;--map-anchor:${size/2}px" data-a="person" data-id="${esc(p.id)}">${p.isKing?`<span class="crown">${icon('crown',21)}</span>`:''}${avatar(p)}<span class="map-node-labels">${compatBadge(p,{compact:true})}<b class="full-name">${compactName(p)}${p.id===db.activeId?' · 나':''}</b><small>${p.isKing?`경배 ${n(p.totalBows)}회 · ${prestige(p)}`:household(db,p.id).length?`식솔 ${household(db,p.id).length}명 · 집안 보유`:pos.isLoyal?`최측근 충신 ${pos.loyalSlot}`:RANKS[rank(p)]}</small></span></button>`;}).join('')}</div></div><div class="map-hint">한 손가락으로 이동 · 두 손가락 벌리기/오므리기 · ＋/− 버튼</div></div><div class="map-caption"><span>${clusters.length}개의 나라 · ${Object.values(db.people).filter(p=>!p.isKing&&!isDependent(db,p)).length}명의 신하 · 식솔 ${Object.values(db.people).filter(p=>isDependent(db,p)).length}명</span><span>초대 관계는 독립해도 유지됩니다. 새 인연은 자동으로 반영됩니다.</span></div>${kingdomRanking()}`;
}

function openModal(content,{wide=false,replace=false,entry=false,tutorial=false}={}){if(!replace)lastFocus=document.activeElement;modal={content,wide,entry,tutorial};$('#modal-root').innerHTML=`<div class="overlay" data-a="overlay"><section class="dialog ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${tutorial?'튜토리얼':'왕실 안내'}">${entry?'':`<button class="dialog-close" data-a="close" aria-label="닫기">${icon('close')}</button>`}${content}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>$('#modal-root input, #modal-root textarea, #modal-root .button, #modal-root button')?.focus(),20);}
function closeModal(){if(modal?.entry&&entryPending)return;if(modal?.tutorial)completeTutorial();modal=null;$('#modal-root').innerHTML='';document.body.style.overflow='';if(lastFocus?.isConnected)lastFocus.focus();setTimeout(checkTutorial,0);}
function start(edit=false){if(!edit&&!demo&&me()){invite=null;go('court');toast('이 브라우저에 저장된 기존 인물로 돌아왔습니다.');return;}const p=edit?me():null,b=p?.birth||{},clock=birthTimeFields(b.time);start.birth=b;start.editId=p?.id||null;start.gender=p?.gender||null;openModal(`<div class="eyebrow">YOUR BIRTH, YOUR DYNASTY</div><h2>${p?'과인의 탄생 기록':invite?'입궐의 사주를 아뢰어라.':'태어난 날을 아뢰어라.'}</h2><p class="lead">사주 기반 성향분석으로 관직과 초상이 자동으로 정해집니다.<br>사주 풀이는 게임 안의 ‘사주 결과 보기’에서만 펼쳐집니다.</p><div class="birth-grid"><label class="field"><span>왕실에서 부를 이름</span><input id="reg-name" maxlength="12" autocomplete="nickname" value="${esc(p?.name||'')}" placeholder="이름 1~12자"><small>별명도 가능합니다. 이름은 사주 계산에 사용하지 않습니다.</small></label><label class="field"><span>생년월일</span><input id="birth-date" type="date" min="1900-01-01" max="2050-12-31" required value="${esc(b.date||'')}"></label><div class="field"><span>달력</span><select id="birth-calendar" aria-label="달력"><option value="solar" ${b.cal!=='lunar'?'selected':''}>양력</option><option value="lunar" ${b.cal==='lunar'?'selected':''}>음력</option></select><label class="check-field"><input id="birth-leap" type="checkbox" ${b.leap?'checked':''}> 음력 윤달</label></div><label class="field"><span>출생지 · 국내</span><select id="birth-city">${BIRTH_REGIONS.map(([region,places])=>`<optgroup label="${esc(region)}">${places.map(([c])=>`<option value="${esc(c)}" ${c===(b.city||'서울')?'selected':''}>${esc(region.split(' · ')[0])} · ${esc(c)}</option>`).join('')}</optgroup>`).join('')}<option value="출생지 모름(국내)" ${b.city==='출생지 모름(국내)'?'selected':''}>출생지 모름(국내)</option></select><small>시·군의 대표 위치로 계산합니다. 목록에 없으면 가까운 지역을 선택해주세요.</small></label><div class="field birth-time-field"><span id="birth-time-label">태어난 시각</span><div class="birth-time-selects" role="group" aria-labelledby="birth-time-label"><select id="birth-period" aria-label="태어난 시간 오전·오후"><option value="unknown" ${clock.period==='unknown'?'selected':''}>시간 모름</option><option value="am" ${clock.period==='am'?'selected':''}>오전</option><option value="pm" ${clock.period==='pm'?'selected':''}>오후</option></select><select id="birth-hour" aria-label="태어난 시" ${clock.period==='unknown'?'disabled':''}><option value="">시</option>${Array.from({length:12},(_,i)=>`<option value="${i+1}" ${clock.hour===String(i+1)?'selected':''}>${i+1}시</option>`).join('')}</select><select id="birth-minute" aria-label="태어난 분" ${clock.period==='unknown'?'disabled':''}><option value="">분</option>${Array.from({length:60},(_,i)=>{const v=String(i).padStart(2,'0');return `<option value="${v}" ${clock.minute===v?'selected':''}>${v}분</option>`;}).join('')}</select></div><small>밤 12시는 오전 12시, 낮 12시는 오후 12시입니다.<br>‘시간 모름’을 고르면 출생 시간을 제외해 풀이합니다.</small></div></div><span class="small">성별</span><div class="gender-grid" style="margin-top:9px">${['M','F'].map(g=>`<button class="gender-choice ${start.gender===g?'selected':''}" data-a="reg-gender" data-value="${g}" aria-pressed="${start.gender===g}" type="button"><img src="assets/lazy-${g==='F'?'queen':'king'}.webp" alt="${g==='F'?'여왕':'왕'}"><b>${g==='F'?'여자 · 여왕':'남자 · 왕'}</b></button>`).join('')}</div><div class="field-error" id="reg-error" role="alert"></div><button class="button full" data-a="birth-start">${p?'사주 정보 적용하기':'사주로 관직·캐릭터 정하고 시작'} ${icon('arrow')}</button><p class="tiny muted" style="margin-top:13px">이 브라우저의 익명 접속 정보로 왕실 기록을 저장합니다. 초대장에는 생년월일시를 넣지 않습니다.</p>`,{wide:true});}
async function completeRegistration({name,gender,birth}){if(!demo){
 const entryRequired=!start.editId;const parent=invite;
 const data=networkSync.active?await networkSync.command({type:'birth',name,gender,birth}):await networkSync.register({name,gender,birth,inviteCode:parent?.code,legacyInviterId:parent?.code?undefined:parent?.id});
 real=data.world;db=real;const p=me();invite=null;quiz=null;closeModal();history.replaceState(null,'',location.pathname+location.search);page=entryRequired?'entry':'court';
 if(entryRequired)entryPending={id:p.id,url:null,busy:false,error:''};render();window.scrollTo(0,0);if(entryRequired)await presentEntryRecovery();else toast('사주 정보를 반영했습니다.');return p;
 }if(!start.editId&&!demo&&me()){returnExistingInvite();go('court');toast('기존 인물로 돌아왔습니다. 새 인물은 만들지 않았습니다.');return me();}const parent=invite,entryRequired=!demo&&(!start.editId||!db.people[start.editId]?.birth);
 if(parent&&!db.people[parent.id]){let previous=null;for(const item of [parent,...parent.ancestors||[]].reverse()){if(!db.people[item.id]){const added=addPerson(db,{...item,scores:TYPES[item.type].p,inviterId:previous,external:true});added.chart=validChart(item.chart)?item.chart:null;applyDestiny(added);}previous=item.id;}}
 const p=start.editId?setBirth(db,start.editId,birth,{name,gender}):addPerson(db,{id:demo?uid():browserSession.id,name,gender,birth,type:0,inviterId:parent?.id||null});db.activeId=p.id;save();invite=null;quiz=null;closeModal();history.replaceState(null,'',location.pathname+location.search);page=entryRequired?'entry':'court';if(entryRequired)entryPending={id:p.id,url:null,busy:false,error:''};render();window.scrollTo(0,0);if(entryRequired)await presentEntryRecovery();else toast('사주에 맞춰 관직과 초상이 다시 정해졌습니다.');return p;}
function compatBadge(p,{compact=false}={}){const king=sovereign(db,p.id),other=p.isKing?(me()?.id!==p.id?me():db.people[p.inviterId]):king;if(!other||other.id===p.id)return '';const c=compatibility(p,other);return `<span class="compat-score">${compact?(p.isKing?'인연':'왕실'):p.isKing?'초대 인연':king?esc(king.name)+kingLabel(king):'왕실'} 궁합 <b>${c?n(c.score)+'점':'사주 등록 후 확인'}</b>${c?.uncertain?'<small>시간 모름·절기 경계 포함</small>':''}</span>`;}
function sajuModal(id=db.activeId){if(id!==db.activeId){toast('개인 사주 풀이는 본인만 확인할 수 있습니다.');return;}const p=db.people[id];if(!p)return;if(!p.birth){start(true);return;}const result=sajuReading(p),r=result.sj.r;openModal(`<div class="eyebrow">ATELIER SAJU · ROYAL RECORD</div><h2>${esc(p.name)}의 사주 결과</h2><p class="tiny muted">아뜰리에 사주 v13 만세력·해석 기반 · 재미용 풀이</p><div class="saju-pillars">${r.detail.map((q,i)=>`<div><small>${['시주','일주','월주','년주'][i]}</small><b>${q?q.stem+q.branch:'—'}</b><span>${q?q.stemK+q.branchK:'시간 모름'}</span></div>`).join('')}</div><div class="note-box">${r.notes.map(esc).join('<br>')||'입력한 생년월일시로 원국을 계산했습니다.'}</div><div class="saju-sections">${result.interpretation.secs.map(sec=>`<details><summary>${sec.t}</summary><div>${sec.items.filter(x=>!x?.hook).map(x=>typeof x==='string'?`<p>${x}</p>`:x.h?`<h3>${x.h}</h3>`:x.b?`<article><b>${x.b}</b><p>${x.t}</p></article>`:x.html?x.html:x.note?`<p class="tiny muted">${x.note}</p>`:'').join('')}</div></details>`).join('')}</div><p class="tiny muted">기존 앱의 해석 문구입니다. 궁합은 사주 규칙만 사용하며, 게임 성향은 일간·오행을 캐릭터로 변환한 놀이 지표입니다.</p>${p.id===db.activeId?'<button class="button light full" data-a="edit-saju">출생 정보 수정</button>':''}`,{wide:true});}


function loyalActions(p){const king=me(),list=loyalSubjects(db,king.id),has=list.some(x=>x.id===p.id);return `<div class="loyal-action"><div><b>${has?'전하가 직접 고른 최측근':'전하의 직권 · 충신 지명'}</b><p>${has?'왕 바로 아래에 놓이는 두 자리 중 하나입니다.':`현재 ${list.length}/2명 · 사주 관직·경배 등급과 별도로 지명합니다.`}</p></div><button class="button ${has?'light':'gold'}" data-a="${has?'loyal-dismiss':'loyal-appoint'}" ${!has&&list.length>=2?'disabled':''}>${has?'충신 해제':'충신으로 삼기'}</button></div>`;}
function destinyCard(p){const t=TYPES[characterType(p)],hasSaju=validChart(p.chart);return `<section class="destiny-card"><div class="eyebrow">${hasSaju?(isDependent(db,p)?'신하가 되면 이어질 사주 관직':'사주가 정한 캐릭터'):'사주 등록 전 캐릭터'}</div><h3>${p.isKing?royalCharacterName(p):officeFor(p)[0]}</h3><p>${esc(destinyDescription(p))}</p><div class="destiny-continuity"><img src="${image(p,true)}" alt="${esc(royalCharacterName(p))} 초상"><div><small>${p.isKing?'왕·여왕 캐릭터':'독립하면 이어지는 군주'}</small><b>${royalCharacterName(p)}</b><span>${p.isKing?`신하일 때의 관직 · ${officeFor(p)[0]}`:t.name}</span></div></div><small class="destiny-note">관직 30종 · 초상은 10가지 성향의 남녀 캐릭터로 연결됩니다. 사주를 게임 캐릭터로 바꾼 재미용 설정입니다.</small></section>`;}
function personModal(id){
 const p=db.people[id];if(!p)return;detailId=id;selectedRank=Math.min(9,rank(p)+1);
 const own=me()?.isKing&&!p.isKing&&p.liegeId===me().id,r=rank(p),dep=isDependent(db,p);
 openModal(`<div class="eyebrow">${p.isKing?'THE INDEPENDENT SOVEREIGN':'A MEMBER OF THE COURT'}</div>
 <div class="person-detail-top"><div class="portrait-circle ${p.isKing?'':dep?'subject dependent':'subject'}" data-frame="${royalStyle(db,p).frame.id}" style="--ring:${border(networkLevelCount(db,sovereign(db,p.id)?.id)).color}"><img src="${image(p)}" alt="${esc(p.name)} 캐릭터"></div>${compatBadge(p)}<h2>${title(p)}</h2><span class="pill ${royalGranted(p)?'gold':''}">${p.isKing?royalCharacterName(p):dep?'식솔 · '+HOUSE_OFFICES[p.houseOffice||0]:`${r+1}등급 · ${RANKS[r]}`}</span>${!p.isKing?`<div class="royal-quote">“${officeFor(p)[1]}”</div>`:''}</div>
 ${destinyCard(p)}${royalLife.personSection(p)}
 ${p.id!==db.activeId?`<button class="button gold full compatibility-detail-button" data-a="compatibility" data-id="${esc(p.id)}">${icon('people',19)} ${me()?.isKing&&!p.isKing?'왕과 신하의':'나와의'} 궁합 사주 보기</button>`:''}
 ${p.isKing?`${royalTreasury(p)}<div class="detail-stat"><span>현직 신하</span><b>${subjects(db,p.id).length}명</b></div><div class="detail-stat"><span>누적 받은 경배 · ${prestige(p)}</span><b>${n(p.totalBows)}회</b></div><div class="detail-stat"><span>왕실 꾸밈</span><b>${royalStyle(db,p).frame.name} · ${royalStyle(db,p).decor.name}</b></div><div class="detail-stat"><span>독립한 군주</span><b>${independent(db,p.id).length}명</b></div><div class="note-box">${p.inviterId&&db.people[p.inviterId]?`${esc(db.people[p.inviterId].name)}의 나라에서 독립했습니다. 이전의 인연은 천하 지도에 남아 있습니다.`:'새 나라를 세운 군주입니다.'}</div><div class="actions">${p.id===db.activeId?'<button class="button light" data-a="my-result">내 사주 결과 보기</button>':''}${demo?`<button class="button" data-a="switch" data-id="${esc(p.id)}">이 인물로 체험</button>`:''}</div>`:
 `<div class="detail-stat"><span>누적 경배</span><b>${n(p.bows)}회</b></div><div class="detail-stat"><span>승급 경로</span><b>${royalGranted(p)?'♛ 낙하산 총애':'정성으로 오른 신하'}</b></div>
 ${own?`${nudgeActions(p)}${loyalActions(p)}<h3 class="favor-heading">왕의 특별 총애</h3><p class="small muted">사주 관직은 그대로 두고, 경배와 관계없이 친밀도 등급을 높입니다.</p><div class="rank-steps">${RANKS.map((name,i)=>`<button class="rank-option ${i===selectedRank?'selected':''}" data-a="rank-select" data-index="${i}" ${i<=r?'disabled':''}><b>${i+1}등급</b>${name}</button>`).join('')}</div><button class="button gold full" style="margin-top:17px" data-a="grant" ${r===9?'disabled':''}>${icon('crown',17)} 특별 총애 내리기</button><p class="tiny muted" style="margin-top:10px">경배 횟수는 유지됩니다. 두 경로 중 높은 등급을 적용합니다.</p>`:''}
 <button class="button light full" style="margin-top:16px" data-a="household" data-id="${esc(p.id)}">${esc(p.name)}의 식솔 ${household(db,p.id).length}명 · 집안 보기</button>
 ${demo?`<div class="actions"><button class="button light" data-a="switch" data-id="${esc(p.id)}">이 신하로 경배 체험</button><button class="button light" data-a="independ-demo" data-id="${esc(p.id)}">독립 체험</button></div>`:''}`}`);
}
function announce(titleText,message,small=''){openModal(`<div class="announcement"><div class="seal">敎</div><div class="eyebrow">A ROYAL DECREE</div><h2>${esc(titleText)}</h2><p>“${esc(message)}”</p>${small?`<small>${esc(small)}</small>`:''}<button class="button full" data-a="close" style="margin-top:25px">왕명을 받들겠나이다</button></div>`,{replace:true});}
function inviteAncestors(p){const out=[];let at=db.people[p.liegeId];while(at&&out.length<499){out.push({id:at.id,name:at.name,gender:at.gender,type:at.type,isKing:at.isKing,chart:at.chart});at=db.people[at.liegeId];}return out;}
function inviteLink(){const p=me();if(!p)return '';if(!demo&&networkSync.state?.invite?.code)return new URL('invite.html?v=3',appBase()).href+'#join='+networkSync.state.invite.code;return new URL('invite.html?v=2',appBase()).href+'#invite='+encode({id:p.id,name:p.name,gender:p.gender,type:p.type,isKing:p.isKing,chart:p.chart,ancestors:inviteAncestors(p)});}
function inviteModal(){if(!me()){start();return;}const p=me();openModal(`<div class="eyebrow">AN INVITATION TO THE COURT</div><h2>과인의 사람이 되겠느냐.</h2><p class="lead">${p.isKing?'초대받은 지인이 사주 정보를 입력하면 나의 신하로 입궐합니다.':'지인이 들어오면 나의 식솔이 됩니다. 남을지 독립할지는 내가 정합니다.'}</p><div class="invite-scroll"><div class="tiny muted">${title(p)}의 초대장</div><p class="serif">왕관은 과인이 쓸 테니,<br>그대는 일단 들어오거라.</p><span class="pill">사주 기반 캐릭터 · 궁합 놀이</span></div><div class="share-preview"><img src="assets/share-preview.jpg" alt="내가왕 초대장 대표 이미지"><div><b>내가왕 · 나는 어떤 왕이 될 상인가?</b><p>사주로 정해지는 나의 왕실 캐릭터</p><small>내가왕 · 성향 놀이</small></div></div><p class="tiny muted" style="margin-top:10px">공유 미리보기 예시 · 실제 표시 모양은 메신저마다 다릅니다.</p><div class="invite-link" tabindex="0">${esc(inviteLink())}</div><div class="actions"><button class="button" data-a="copy-invite">링크 복사</button><button class="button light" data-a="share-invite">초대장 공유</button></div><div class="note-box"><b>현재는 초안 체험판입니다.</b><br>내 왕실 기록은 서버에 자동 저장됩니다. 초대받은 사람이 다시 지인을 초대하면 같은 천하에 계속 연결됩니다. 독립해도 초대 관계는 유지되며, 새 활동은 약 10초마다 확인합니다. 사이트의 현재 접근 범위는 소유자 전용입니다. 메신저의 실제 이미지 미리보기는 공개 접근 허용 후 확인할 수 있습니다.</div>${demo?'<button class="text-btn" style="margin-top:15px" data-a="sample-add">체험용 신하를 지금 입궐시키기 ↗</button>':''}`);}
function sampleAdd(inviterId=db.activeId){if(!demo)return;sampleAdd.inviter=inviterId;const p=db.people[inviterId];openModal(`<div class="eyebrow">PREVIEW ONLY</div><h2>샘플 지인 입궐</h2><p class="lead">${esc(p.name)}의 초대를 받은 지인이 사주 입력까지 마친 상황을 체험합니다.${!p.isKing?'<br>이 지인은 먼저 식솔이 됩니다. 초대한 인물로 전환해 잔류·독립을 고를 수 있습니다.':''}</p><label class="field"><span>체험용 이름</span><input id="sample-name" maxlength="12" value="새 지인"></label><label class="field"><span>성별</span><select id="sample-gender"><option value="M">남자 · 독립 시 왕</option><option value="F">여자 · 독립 시 여왕</option></select></label><div class="field-error" id="sample-error" role="alert"></div><button class="button full" data-a="sample-confirm">사주 입력 완료 · 입궐시키기</button><p class="tiny muted" style="margin-top:12px">샘플 인물에게는 체험용 성향이 자동 배정됩니다.</p>`);}
function about(){openModal(`<div class="eyebrow">ABOUT THIS LITTLE DYNASTY</div><h2>작은 조정 사용설명서</h2><p class="lead">성향으로 나를 발견하고, 사람들과 작은 왕국을 만드는 놀이입니다.</p><div class="tutorial-roles"><button class="button light" data-a="tutorial-role" data-role="subject">신하 튜토리얼</button><button class="button light" data-a="tutorial-role" data-role="king">왕 튜토리얼</button></div><div class="how-list"><div><b>사주로 내 캐릭터 완성</b><br>사주로 읽은 10가지 성향에 따라 남녀별 신하 초상과 왕·여왕 초상이 자동 배정됩니다. 관직은 세부 기질에 따라 30종으로 나뉩니다.</div><div><b>신하·식솔도 나라를 세울 수 있습니다</b><br>초대한 지인이 들어오면 식솔이 됩니다. 잔류·독립은 직접 고르며, 옛 인연은 남습니다.</div><div><b>경배와 특별 총애로 등급 상승</b><br>관직은 사주로 자동 결정됩니다. 왕은 특별 총애로 친밀도 등급을 높이고 최측근 충신 두 명을 지명합니다.</div></div><div class="note-box">초대 관계로 이어진 사람들이 하나의 천하를 함께 보는 버전입니다. 샘플 조정은 실제 기록과 분리됩니다. 고정 복구 링크는 이 브라우저의 최신 서버 저장본으로 돌아옵니다. 초대·독립·경배·어전회의 기록은 공유 서버에 반영되며 약 10초마다 새 활동을 확인합니다. 생년월일시는 본인에게만 표시합니다. 재미용 성향 놀이이며 전문 심리검사가 아닙니다.</div><div class="actions"><button class="button" data-a="close">알겠노라</button>${real.activeId?'<button class="button light" data-a="reset">내 기록 초기화</button>':''}</div>`);}
function ranksModal(){openModal(`<div class="eyebrow">THE LADDER OF ROYAL AFFECTION</div><h2>총애에도 순서가 있느니라.</h2><p class="lead">경배가 쌓이면 자동 승급합니다.<br>왕의 특별 총애는 경배와 상관없이 등급을 올립니다.</p><table class="rank-table"><tbody>${RANKS.map((r,i)=>`<tr><td>${i+1}등급</td><td>${r}</td><td>${n(THRESHOLDS[i])}회</td></tr>`).join('')}</tbody></table><div class="note-box">순위는 누적 경배 횟수 순입니다. 다른 신하에게 추월당해도 획득한 친밀 등급은 내려가지 않습니다.</div><button class="button full" style="margin-top:20px" data-a="close">확인하였노라</button>`);}
async function copy(text,{label='초대장 링크',message='초대장을 복사했습니다.'}={}){if(navigator.clipboard?.writeText){try{await navigator.clipboard.writeText(text);toast(message);return;}catch{}}openModal(`<h2>${esc(label)}</h2><p class="lead">아래 링크를 길게 눌러 복사해주세요.</p><label class="field"><span>${esc(label)}</span><input id="copy-fallback" readonly value="${esc(text)}"></label><button class="button full" data-a="close">확인</button>`);setTimeout(()=>$('#copy-fallback')?.select(),30);}
async function recoveryModal(){
 recoveryPrepared=null;let own=real.people[real.activeId];openModal('<div class="eyebrow">RETURN TO YOUR KINGDOM</div><h2>왕실 복귀 주소</h2><p class="lead">서버의 최신 저장 상태를 확인하고 있습니다.</p>');const expected=modal;let problem='';
 if(own){try{if(!cloudSync.ready)await initializeServer();if(!networkSync.active&&cloudSync.status==='conflict')throw Error('다른 기기의 최신 기록을 먼저 불러와주세요.');await (networkSync.active?networkSync.flush():cloudSync.flush());if(['error','signin'].includes(networkSync.active?cloudStatus:cloudSync.status))throw Error(cloudMessage||'서버 저장 연결이 필요합니다.');own=real.people[real.activeId];recoveryPrepared={url:latestReturnLink(),packet:makeBackup(real),length:latestReturnLink().length};}catch(e){problem=e.message;}}
 if(modal!==expected)return;let previous=false;try{previous=!!localStorage.getItem(PREVIOUS_KEY);}catch{}
 openModal(`<div class="eyebrow">RETURN TO YOUR KINGDOM</div><h2>언제든, 과인의 나라로.</h2><p class="lead">복구 링크는 변하지 않습니다.<br>이 브라우저에서는 자동으로 돌아옵니다. 다른 브라우저에서는 나만의 복구 링크로 최신 저장본을 불러옵니다.</p>${own?`<div class="backup-summary"><span class="seal">歸</span><div><b>${esc(own.name)}${own.isKing?kingLabel(own):'의 기록'}</b><p>식솔·독립·금화·꾸밈·곤장 전교까지 자동 저장</p></div></div>${recoveryPrepared?`<label class="field"><span>나만의 고정 복구 링크</span><textarea class="backup-link" readonly id="recovery-link" rows="2">${esc(recoveryPrepared.url)}</textarea></label><div class="actions"><button class="button" data-a="copy-recovery">고정 링크 복사</button><button class="button light" data-a="backup-download">별도 백업 파일</button></div><div class="note-box"><b>예전 링크를 다시 만들어둘 필요가 없습니다.</b><br>이 주소는 최신 저장본에 접근할 수 있는 개인 복구 정보입니다. 초대장과 별개이며 다른 사람에게 공유하지 마세요. ‘최신 기록 저장됨’ 표시를 확인한 변경 사항이 다른 기기에도 이어집니다.</div>`:`<div class="note-box">${esc(problem||'저장 연결을 먼저 확인해주세요.')}</div><button class="button full" style="margin-top:13px" data-a="cloud-latest">서버의 최신 왕실 확인</button>`}`:`<div class="note-box">${demo?'샘플 조정은 개인 서버 기록에 저장하지 않습니다.':'아직 내 왕실 기록이 없습니다.'} 이미 기록이 있다면 복구 링크나 백업으로 최신 왕실을 불러오세요.</div><button class="button full" style="margin-top:12px" data-a="cloud-latest">최신 왕실 불러오기</button>`}<div class="recovery-divider"></div><h3 style="font-size:18px">이전 백업을 옮겨오기</h3><p class="tiny muted" style="margin-top:8px">예전에 만든 스냅샷 링크·백업 파일도 가져올 수 있습니다. 가져온 뒤에는 서버에 새 최신 기록으로 저장됩니다.</p><label class="field"><span>이전 복구 링크 또는 코드</span><textarea id="restore-input" class="backup-link" rows="2" placeholder="이전 스냅샷 링크를 붙여넣으세요."></textarea></label><div class="field-error" id="recovery-error" role="alert"></div><button class="button jade full" data-a="restore-input">이전 백업 내용 확인</button><label class="backup-file">백업 파일에서 불러오기<input id="restore-file" type="file" accept=".json,application/json"></label>${previous?'<button class="text-btn" data-a="restore-previous">가져오기 전의 기록 확인 ↗</button>':''}`,{replace:true});
}

async function inspectRecovery(input){
 if(recoveryBusy)return;recoveryBusy=true;pendingRestore=null;try{const packet=await readRecovery(input);pendingRestore=packet;const world=packet.world,p=world.people[world.activeId];openModal(`<div class="eyebrow">RESTORE THE DYNASTY</div><h2>이 왕실로 돌아갈까요?</h2><div class="backup-summary"><span class="seal">復</span><div><b>${esc(p.name)}${p.isKing?kingLabel(p):' · 신하'}</b><p>인물 ${Object.keys(world.people).length}명 · ${new Date(packet.savedAt).toLocaleString('ko-KR')}</p></div></div><div class="detail-stat"><span>나의 군주 성향</span><b>${TYPES[characterType(p)].name}</b></div><div class="detail-stat"><span>관직·경배·독립 기록</span><b>함께 복원</b></div><div class="note-box">복구 링크를 만든 시점으로 돌아갑니다.${real.activeId?' 현재 브라우저의 기록은 별도로 보관하며, 보관함에서 되돌릴 수 있습니다.':''} 다른 기기에서 바뀐 내용이 실시간으로 합쳐지지는 않습니다.</div><div class="actions"><button class="button light" data-a="close">돌아가기</button><button class="button" data-a="restore-confirm">이 왕실로 복원</button></div>`);
 }catch(e){if(modal&&$('#recovery-error')){$('#recovery-error').textContent=e.message;}else openModal(`<h2>복구 링크를 확인해주세요.</h2><p class="lead">${esc(e.message)}</p><button class="button full" data-a="recovery">복구 보관함 열기</button>`);toast(e.message);}finally{recoveryBusy=false;}
}
function confirmRestore(){if(!pendingRestore)return;if(networkSync.active){toast('공유 천하는 개인 복구 링크로 돌아와주세요. 과거 백업으로 다른 사람의 최신 기록을 덮어쓸 수 없습니다.');return;}const world=validateWorld(pendingRestore.world);try{if(real.activeId)localStorage.setItem(PREVIOUS_KEY,JSON.stringify(makeBackup(real)));localStorage.setItem(KEY,JSON.stringify(world));}catch{toast('기록을 저장할 공간이 없습니다. 현재 기록은 그대로 유지합니다.');return;}real=world;db=world;demo=false;quiz=null;quizBusy=false;invite=null;pendingRestore=null;saveError=false;try{localStorage.setItem(DIRTY_KEY,'1');}catch{}cloudSync.schedule(real);history.replaceState(null,'',location.pathname+location.search);go('court');toast('왕실 기록을 복원했습니다.');}
function downloadBackup(){if(!real.activeId)return;const packet=recoveryPrepared?.packet||makeBackup(real),blob=new Blob([JSON.stringify(packet)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='naegawang-backup-'+new Date(packet.savedAt).toISOString().slice(0,10)+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('백업 파일을 저장합니다.');}

function go(p){if(networkSync.active)refreshNetwork();closeModal();quizBusy=false;if(p==='court'&&!me())p='landing';page=p;render();window.scrollTo(0,0);}
async function action(a,b){if(!modal?.tutorial&&!entryPending&&!serverBooting&&!demo&&networkSync.active){const cmd=networkAction(a,b);if(cmd){try{await runNetworkAction(a,b,cmd);}catch(e){toast(e.message);}return;}}try{if(modal?.tutorial&&!['tutorial-next','tutorial-prev','tutorial-practice','tutorial-skip','tutorial-finish','close','overlay'].includes(a))return;if(entryPending&&!['entry-copy','entry-retry','entry-enter','backup-download'].includes(a))return;if(serverBooting&&!demo&&['start','birth-start','edit-saju','grant','loyal-appoint','loyal-dismiss','reset-confirm','restore-confirm','bow','reign-stay','reign-independent','shop-equip','royal-nudge','house-role','nudge-ack','life-council-open','life-council-vote','life-council-close'].includes(a)){toast('최신 왕실을 연결하고 있습니다. 잠시만 기다려주세요.');return;}if(a.startsWith('life-')){await royalLife.handle(a,b);return;}switch(a){
 case 'tutorial':me()?startTutorial():tutorialChooser();break;
 case 'tutorial-role':startTutorial(b.dataset.role);break;
 case 'tutorial-prev':if(tutorialState){tutorialState.step=Math.max(0,tutorialState.step-1);drawTutorial();}break;
 case 'tutorial-next':if(tutorialState&&tutorialState.step<tutorialState.steps.length-1){tutorialState.step++;drawTutorial();}break;
 case 'tutorial-practice':if(tutorialState){const kind=tutorialState.steps[tutorialState.step].practice;if(kind){tutorialState[kind]=Math.min(kind==='favor'?RANKS.length-1:999,tutorialState[kind]+1);drawTutorial();}}break;
 case 'tutorial-skip':case 'tutorial-finish':closeModal();break;
 case 'entry-copy':{if(!entryPending?.url)return;const url=entryPending.url;try{if(!navigator.clipboard?.writeText)throw Error();await navigator.clipboard.writeText(url);toast('복구 링크를 복사했습니다. 안전한 곳에 보관해주세요.');}catch{$('#entry-recovery-link')?.focus();$('#entry-recovery-link')?.select();toast('표시된 복구 링크를 길게 눌러 복사해주세요.');}break;}
 case 'entry-retry':await presentEntryRecovery();break;
 case 'entry-enter':if(entryPending&&!entryPending.busy){entryPending=null;closeModal();page='court';render();window.scrollTo(0,0);}break;
 case 'home':go(me()?'court':'landing');break;
 case 'nav':if(quiz){openModal('<h2>문답을 잠시 멈출까요?</h2><p class="lead">나중에 다시 시작하면 처음부터 답하게 됩니다.</p><div class="actions"><button class="button light" data-a="close">계속 답하기</button><button class="button" data-a="leave-quiz" data-page="'+esc(b.dataset.page)+'">문답 나가기</button></div>');}else go(b.dataset.page);break;
 case 'leave-quiz':quiz=null;go(b.dataset.page);break;
 case 'about':about();break;case 'cloud-latest':await showLatestChoice();break;case 'cloud-load-confirm':keepPrevious();closeModal();await initializeServer({preferLatest:true});break;case 'loyal-appoint':{const p=db.people[detailId];appointLoyal(db,db.activeId,p.id);save();render();announce(`${p.name}, 전하의 최측근 충신`, '경배가 많아서가 아니다. 과인이 그대를 믿기 때문이다.','왕 바로 아래 두 자리 중 하나에 배치됩니다.');break;}case 'loyal-dismiss':{dismissLoyal(db,db.activeId,detailId);save();render();personModal(detailId);break;}case 'recovery':await recoveryModal();break;case 'copy-recovery':if(recoveryPrepared)await copy(recoveryPrepared.url,{label:'개인 복구 링크',message:'개인 복구 링크를 복사했습니다. 안전한 곳에 보관해주세요.'});break;case 'backup-download':downloadBackup();break;case 'restore-input':await inspectRecovery($('#restore-input').value);break;case 'restore-confirm':confirmRestore();break;case 'restore-previous':{const old=localStorage.getItem(PREVIOUS_KEY);if(old)await inspectRecovery(old);break;}case 'map-households':showHouseholds=!showHouseholds;render();break;case 'map-in':mapController?.zoom(1.25);break;case 'map-out':mapController?.zoom(.8);break;case 'map-fit':mapController?.fit();break;case 'map-center':mapController?.center();break;case 'ranks':ranksModal();break;case 'close':closeModal();break;
 case 'overlay':if(b===eventTarget)closeModal();break;
 case 'start':if(demo){demo=false;db=real;}quiz=null;start();break;
 case 'reg-gender':start.gender=b.dataset.value;document.querySelectorAll('.gender-choice').forEach(x=>{x.classList.toggle('selected',x.dataset.value===start.gender);x.setAttribute('aria-pressed',String(x.dataset.value===start.gender));});break;
 case 'birth-start':{if(registrationBusy)return;registrationBusy=true;const name=$('#reg-name').value.trim(),gender=start.gender;try{if(!name||[...name].length>12)throw Error('이름은 1~12자로 아뢰어 주세요.');if(!gender)throw Error('성별을 선택해주세요.');const birth={date:$('#birth-date').value,time:birthTimeValue($('#birth-period').value,$('#birth-hour').value,$('#birth-minute').value),cal:$('#birth-calendar').value||'solar',leap:!!$('#birth-leap').checked,city:$('#birth-city').value||'서울',timeMode:start.birth?.timeMode||'lmt',zishi:start.birth?.zishi||'unified',dstFold:start.birth?.dstFold||'earlier'};analyzeBirth(birth,gender);if(!start.editId&&!demo){await initializeServer({preferLatest:true});if(!cloudSync.ready||['error','signin','conflict'].includes(cloudSync.status))throw Error(cloudMessage||'접속 기록을 확인한 뒤 입장할 수 있습니다.');}await completeRegistration({name,gender,birth});}catch(e){$('#reg-error').textContent=e.message;}finally{registrationBusy=false;}break;}
 case 'demo':if(!demo){db=makeDemo();demo=true;}page=b.dataset.page||'court';closeModal();render();window.scrollTo(0,0);break;
 case 'exit-demo':demo=false;db=real;go(me()?'court':'landing');break;
 case 'my-result':case 'saju-result':sajuModal();break;
 case 'edit-saju':start(true);break;
 case 'household':householdModal(b.dataset.id);break;
 case 'house-role':{const p=db.people[b.dataset.id];assignHousehold(db,db.activeId,p.id,((p.houseOffice||0)+1)%HOUSE_OFFICES.length);save();render();householdModal(b.dataset.owner);break;}
 case 'reign-stay':chooseStay(db,db.activeId);save();render();toast('이 집안에 남아 식솔을 돌봅니다. 나중에도 독립할 수 있습니다.');break;
 case 'reign-independent':{const p=becomeKing(db,db.activeId);save();render();announce(`${p.name}${kingLabel(p)} 즉위`,'과인도 이제 내 나라를 다스리겠노라.','직속 식솔은 신하로, 그 아래 집안은 그대로. 옛 인연은 지도에 남습니다.');break;}
 case 'royal-shop':shopModal();break;
 case 'shop-equip':royalShop(db,db.activeId,b.dataset.kind,b.dataset.id);save();render();shopModal();break;
 case 'royal-nudge':royalNudge(db,db.activeId,detailId);save();render();personModal(detailId);toast('딱! 경배를 빨리 하라는 전교를 내렸습니다.');break;
 case 'nudge-ack':acknowledgeNudge(db,db.activeId);save();closeModal();page='court';render();break;
 case 'compatibility':compatibilityModal(b.dataset.id);break;
 case 'saju-person':sajuModal(b.dataset.id);break;
 case 'person':personModal(b.dataset.id);break;
 case 'person-type':sajuModal(b.dataset.id);break;
 case 'rank-select':selectedRank=Number(b.dataset.index);document.querySelectorAll('.rank-option').forEach(x=>x.classList.toggle('selected',Number(x.dataset.index)===selectedRank));break;
 case 'appoint':case 'office-select':toast('관직은 사주로 자동 부여됩니다. 왕은 친밀도 등급과 충신 자리만 정할 수 있습니다.');break;
 case 'grant':{const p=db.people[detailId];grant(db,db.activeId,p.id,selectedRank);save();render();announce(`${p.name} · ${RANKS[selectedRank]}`,'경배는 부족하나, 과인이 좋아하므로 올린다.','경배 '+n(p.bows)+'회는 그대로 · 낙하산 총애');break;}
 case 'bow':{const p=me(),old=rank(p);bow(db,p.id,p.liegeId);save();const r=rank(p),next=THRESHOLDS[r+1];$('#bow-number').textContent=n(p.bows);$('#king-bow-total').textContent=n(db.people[p.liegeId].totalBows);$('#king-gold').textContent=n(db.people[p.liegeId].gold);$('#rank-progress').innerHTML=`<span class="pill gold">${r+1}등급 · ${RANKS[r]}</span><div class="progress"><i style="width:${next?Math.min(100,p.bows/next*100):100}%"></i></div><span class="tiny muted">${next?`다음 등급까지 ${n(next-p.bows)}회`:'전하의 총애가 지극하옵니다.'}</span>`;const portrait=$('.bow-stage .avatar');portrait?.classList.remove('bow-flash');if(portrait){void portrait.offsetWidth;portrait.classList.add('bow-flash');}if(r>old)toast(`정성이 닿았습니다. 「${RANKS[r]}」 승급!`);royalLife.refresh();break;}
 case 'switch':if(demo){db.activeId=b.dataset.id;closeModal();go('court');}break;
 case 'independ-demo':if(demo)sampleAdd(b.dataset.id);break;
 case 'sample-add':sampleAdd();break;
 case 'sample-confirm':{if(!demo)break;const name=$('#sample-name').value.trim(),gender=$('#sample-gender').value,parent=db.people[sampleAdd.inviter];try{addPerson(db,{id:uid(),name,gender,type:0,birth:{date:'1995-06-15',time:'09:00',city:'서울'},inviterId:parent.id});}catch(e){$('#sample-error').textContent=e.message;break;}closeModal();if(!parent.isKing)db.activeId=parent.id;render();if(!parent.isKing)toast(`${name}이 식솔로 들어왔습니다. 잔류 또는 독립을 골라주세요.`);else announce(`${name}, 입궐하였사옵니다.`,'시키시는 일은 무엇이든 하겠사옵니다. 일단 말씀만 하십시오.','샘플 인물이 조정에 추가되었습니다.');break;}
 case 'invite':inviteModal();break;
 case 'copy-invite':await copy(inviteLink());break;
 case 'share-invite':{const link=inviteLink();if(navigator.share){try{await navigator.share({title:'내가왕 · 과인의 조정에 들겠느냐',text:'나는 어떤 군주일까? 사주 정보 입력으로 왕실 캐릭터를 확인해보세요.',url:link});}catch(e){if(e.name!=='AbortError')await copy(link);}}else await copy(link);break;}
 case 'reset':if(networkSync.active){toast('공유 천하의 인연을 보존하기 위해 전체 초기화는 제공하지 않습니다. 개인 복구 링크를 보관해주세요.');break;}openModal('<h2>내 조정을 초기화할까요?</h2><p class="lead">이 브라우저에 저장된 내가왕 인물과 경배·관직 기록을 지웁니다. 이전 사주 앱의 기록은 건드리지 않습니다.</p><div class="actions"><button class="button light" data-a="close">돌아가기</button><button class="button" data-a="reset-confirm">내가왕 기록 지우기</button></div>');break;
 case 'reset-confirm':if(networkSync.active)break;await cloudSync.remove();real=newWorld();if(!demo)db=real;try{localStorage.removeItem(KEY);localStorage.removeItem(DIRTY_KEY);localStorage.removeItem(REV_KEY);}catch{}closeModal();if(!demo)page='landing';render();toast('내가왕 기록을 초기화했습니다.');break;
 }}catch(e){toast(e.message||'잠시 후 다시 시도해주세요.');}}
let eventTarget=null;
document.addEventListener('click',e=>{const b=e.target.closest('[data-a]');if(e.defaultPrevented||!b||b.disabled)return;eventTarget=e.target;action(b.dataset.a,b);});
document.addEventListener('change',e=>{if(e.target.id==='birth-period'){const unknown=e.target.value==='unknown';$('#birth-hour').disabled=unknown;$('#birth-minute').disabled=unknown;return;}if(e.target.id==='restore-file'){const f=e.target.files?.[0];if(f){if(f.size>512000){toast('백업 파일이 너무 큽니다.');return;}f.text().then(inspectRecovery).catch(()=>toast('백업 파일을 읽을 수 없습니다.'));}return;}if(e.target.id==='demo-person'&&demo&&db.people[e.target.value]){db.activeId=e.target.value;go('court');}});
document.addEventListener('keydown',e=>{if(!modal)return;if(e.key==='Escape'){e.preventDefault();if(!modal.entry)closeModal();return;}if(e.key==='Tab'){const items=[...document.querySelectorAll('.dialog button:not(:disabled), .dialog input, .dialog textarea, .dialog select, .dialog a[href], .dialog [tabindex="0"]')];if(!items.length)return;const a=items[0],z=items.at(-1);if(e.shiftKey&&document.activeElement===a){e.preventDefault();z.focus();}else if(!e.shiftKey&&document.activeElement===z){e.preventDefault();a.focus();}}});
window.addEventListener('hashchange',()=>{if(new URLSearchParams(location.hash.slice(1)).has('restore'))inspectRecovery(location.href);else if(new URLSearchParams(location.hash.slice(1)).has('guest')){recoveryHandled=false;initializeServer({preferLatest:true});}else{readInvite();render();}});
window.addEventListener('storage',e=>{if(e.key===SESSION_KEY){if(!demo){cloudSync.pause();toast('다른 탭에서 접속 정보가 바뀌었습니다. 새로고침해주세요.');}return;}if(e.key===KEY&&!demo&&!quiz&&!modal){real=readWorld();db=real;page=me()?page:'landing';render();}});
render();

if(new URLSearchParams(location.hash.slice(1)).has('restore'))inspectRecovery(location.href);

initializeServer();
window.addEventListener('pagehide',()=>{if(networkSync.active){networkSync.flush().catch(()=>{});return;}if(cloudSync.hasPending)cloudSync.flush().catch(()=>{});});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&cloudSync.hasPending)cloudSync.flush().catch(()=>{});else if(document.visibilityState==='visible'&&cloudSync.status==='saved'&&!demo&&!quiz&&!modal)initializeServer();});
window.addEventListener('pageshow',e=>{if(e.persisted&&!demo&&!quiz)initializeServer();});

function entryView(){return `<section class="entry-welcome"><span class="seal">歸</span><div class="eyebrow">ONE LAST THING BEFORE YOU ENTER</div><h1>왕실 입장을 준비했습니다.</h1><p>아직 입장 전입니다. 복구 링크 안내를 확인해주세요.</p><button class="button light" data-a="entry-retry">복구 링크 안내 다시 보기</button></section>`;}
function entryRecoveryContent(){const state=entryPending;return `<div class="entry-recovery"><span class="seal">歸</span><div class="eyebrow">KEEP YOUR WAY BACK</div><h2>입장 전, 복구 링크를 보관하세요.</h2><p class="lead">같은 브라우저에서는 기존 인물로 자동 접속합니다. 이 링크는 브라우저 기록 삭제·기기 변경에 대비한 복귀 주소입니다.</p><div class="entry-warning"><b>복구 링크 없이 다시 접속하면 처음부터 시작해야 할 수 있습니다.</b><p>링크를 잃어버리고 브라우저 정보가 삭제되거나 다른 브라우저를 사용하면, 기존 왕실을 찾지 못해 초기화된 화면이 나타날 수 있습니다.</p></div>${state.url?`<label class="field"><span>나만의 고정 복구 링크 · 최신 기록으로 복귀</span><textarea class="backup-link" id="entry-recovery-link" readonly rows="3">${esc(state.url)}</textarea></label><div class="actions"><button class="button" data-a="entry-copy">복구 링크 복사</button><button class="button light" data-a="backup-download">백업 파일 보관</button></div>`:state.busy?'<p class="entry-saving" role="status">최신 왕실 기록을 서버에 저장하고 복구 링크를 준비하고 있습니다.</p>':`<div class="entry-save-error" role="alert"><b>서버 저장을 아직 완료하지 못했습니다.</b><p>${esc(state.error)}</p><p>복구 링크는 서버 저장 후 사용할 수 있습니다. 지금은 백업 파일을 따로 보관해주세요.</p><div class="actions"><button class="button light" data-a="entry-retry">저장 다시 시도</button><button class="button light" data-a="backup-download">백업 파일 보관</button></div></div>`}<div class="note-box"><b>게임 안에서도 언제든 다시 확인할 수 있습니다.</b><br>상단·하단의 ‘복구 링크’ 버튼에서 링크를 다시 복사하거나 보관할 수 있습니다. 같은 브라우저에서는 자동 접속됩니다. 브라우저 기록을 지우거나 다른 브라우저를 쓰면 복구 링크가 필요합니다.</div><button class="button full" style="margin-top:24px" data-a="entry-enter" ${state.busy?'disabled':''}>${state.error?'안내 확인 · 임시로 게임 입장':'안내 확인 · 게임 입장'}</button></div>`;}
async function presentEntryRecovery(){const state=entryPending;if(!state||state.busy)return;state.busy=true;state.error='';openModal(entryRecoveryContent(),{wide:true,entry:true,replace:!!modal?.entry});try{if(!networkSync.active&&cloudSync.status==='conflict')throw Error('다른 기기의 새 기록을 먼저 확인해야 합니다.');await (networkSync.active?networkSync.flush():cloudSync.flush());if(['error','signin','conflict'].includes(networkSync.active?cloudStatus:cloudSync.status))throw Error(cloudMessage||'서버 저장 연결을 확인해주세요.');state.url=latestReturnLink();}catch(e){state.error=e.message||'서버에 연결하지 못했습니다.';}finally{state.busy=false;if(entryPending===state)openModal(entryRecoveryContent(),{wide:true,entry:true,replace:true});}}

function compatibilityModal(id){let a=me(),b=db.people[id];if(!a||!b)return;if(a.id===b.id)b=sovereign(db,a.id);if(!b||a.id===b.id){toast('궁합을 확인할 신하를 골라주세요.');return;}const report=compatibilityReport(a,b);if(!report){openModal(`<div class="eyebrow">ROYAL COMPATIBILITY</div><h2>두 사람의 사주 정보가 필요합니다.</h2><p class="lead">${title(a)} · ${title(b)}의 사주 요약이 모두 등록되면 궁합 점수와 해석을 확인할 수 있습니다.</p>${!a.chart?'<button class="button full" data-a="edit-saju">내 사주 정보 등록</button>':'<p class="note-box">상대의 사주 정보 등록을 기다려주세요. 정보 없이 점수를 만들지 않습니다.</p>'}`);return;}
 openModal(`<div class="eyebrow">ATELIER SAJU · ROYAL COMPATIBILITY</div><h2>우리의 궁합 사주</h2><div class="compatibility-pair"><div>${avatar(a)}<b>${title(a)}</b></div><span class="pair-knot">緣</span><div>${avatar(b)}<b>${title(b)}</b></div></div><div class="compatibility-score-panel"><small>사주 궁합 점수</small><strong>${n(report.score)}<span>점</span></strong><b>${report.summary}</b><p>두 사람의 어울림을 쉬운 말로 풀어드립니다.</p></div><div class="compatibility-reasons">${report.explanation.map(section=>`<article><h3>${esc(section.title)}</h3>${section.paragraphs.map(text=>`<p>${esc(text)}</p>`).join('')}</article>`).join('')}</div><div class="note-box">${report.readingNotes.map(esc).join('<br>')}</div><button class="button full" style="margin-top:20px" data-a="close">궁합 확인했소</button>`,{wide:true});}

